totalNodes=0; for i in $(k config get-contexts --no-headers | tr -d '*' | awk '{print $1}'); do k config use $i; nodes=$(k get nodes | wc -l); totalNodes=`echo "$totalNodes + $nodes" | bc`; done; echo totalNodes=$totalNodes
totalPods=0; for i in $(k config get-contexts --no-headers | tr -d '*' | awk '{print $1}'); do k config use $i; pods=$(k get pods --all-namespaces | wc -l); totalPods=`echo "$totalPods + $pods" | bc`; done; echo totalPods=$totalPods
totalContainers=0; for i in $(k config get-contexts --no-headers | tr -d '*' | awk '{print $1}'); do k config use $i; containers=$(k get pods --all-namespaces -o jsonpath="{.items[*].spec.containers[*].name}" | tr -s ' ' '\n' | wc -l); totalContainers=`echo "$totalContainers + $containers" | bc`; done; echo totalContainers=$totalContainers